parameters.jsCode:
const MAX_CHARS = 150000;
const SIMILARITY_THRESHOLD = 0.9;

// Near-duplicate, not exact: the same facts file exported as a Google Doc and as
// markdown differs in bullet glyphs, line endings and heading markers, and one copy
// is usually a few edits behind the other. Trigram Jaccard sees through all of that.
const shingles = (s) => {
  const w = (s.toLowerCase().match(/[a-z0-9]+/g) || []);
  const set = new Set();
  for (let i = 0; i + 2 < w.length; i++) set.add(w[i] + ' ' + w[i + 1] + ' ' + w[i + 2]);
  return set;
};

const jaccard = (a, b) => {
  if (!a.size || !b.size) return 0;
  let shared = 0;
  for (const s of a) if (b.has(s)) shared++;
  return shared / (a.size + b.size - shared);
};

const skipped = [];
const candidates = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const name = j.fileName || 'unnamed file';
  const text = (j.extractedText || '').trim();

  if (j.ok === false || !text) {
    skipped.push(name + (j.error ? ' (' + j.error + ')' : ''));
    continue;
  }

  candidates.push({ name, text, shingles: shingles(text) });
}

// Longest first so that when two copies are near-identical the fuller one survives.
candidates.sort((a, b) => b.text.length - a.text.length);

const kept = [];
for (const c of candidates) {
  const dupeOf = kept.find(k => jaccard(k.shingles, c.shingles) >= SIMILARITY_THRESHOLD);
  if (dupeOf) {
    skipped.push(c.name + ' (near-duplicate of ' + dupeOf.name + ' - kept the longer copy)');
    continue;
  }
  kept.push(c);
}

let corpus = '';
const included = [];

for (const c of kept) {
  const block = '\n\n===== SOURCE FILE: ' + c.name + ' =====\n' + c.text;
  if (corpus.length + block.length > MAX_CHARS) {
    skipped.push(c.name + ' (skipped - corpus size limit reached)');
    continue;
  }
  corpus += block;
  included.push(c.name);
}

if (!corpus.trim()) {
  throw new Error('No readable resume material was found in the Google Drive source folder. Add a Google Doc, PDF, Word doc, or .txt file to it and try again.');
}

return [{ json: { corpus: corpus.trim(), includedFiles: included, skippedFiles: skipped } }];

