const a = $('Analyze JD Against Profile').first().json.output || {};
const role = String(a.role_title || '').trim();
const location = String(a.location || '').trim();

// 'Unknown Role' is the extractor's documented fallback - don't search for it literally.
const subject = (role && role !== 'Unknown Role') ? role : 'this job';

// Scoped to ATS/job-board domains: an unscoped 'job description requirements'
// search returns resume-advice articles, not the live postings we need to count
// keyword demand against.
const boards = [
  'site:boards.greenhouse.io',
  'site:job-boards.greenhouse.io',
  'site:jobs.lever.co',
  'site:jobs.ashbyhq.com',
  'site:wellfound.com',
  'site:builtin.com',
].join(' OR ');

const postingsQuery = [
  subject,
  '("responsibilities" OR "about the role" OR "requirements")',
  location,
  '(' + boards + ')',
].filter(Boolean).join(' ');

return [
  {
    json: {
      purpose: 'postings',
      query: postingsQuery.slice(0, 500),
      scrape: true,
      limit: 5,
    },
  },
  {
    json: {
      purpose: 'rubric',
      query: (subject + ' resume best practices what recruiters look for ATS keywords').slice(0, 500),
      scrape: false,
      limit: 5,
    },
  },
];

const MAX_CORPUS = 40000;
const MAX_RUBRIC = 8000;

const queries = $('Build Research Queries').all();
const results = $input.all();
const jd = $('Analyze JD Against Profile').first().json.output || {};
const keywords = (jd.keywords || []).map(k => String(k).trim()).filter(Boolean).slice(0, 25);

const webResults = (item) => {
  const data = item && item.json && item.json.data;
  return data && Array.isArray(data.web) ? data.web : [];
};

// onError=continueRegularOutput turns a failed search into a data item, not a
// thrown error - without this check a 429 reads as 'zero results' downstream.
const errorOf = (item) => {
  const e = item && item.json && item.json.error;
  if (!e) return null;
  const status = e.status || e.httpCode;
  if (status === 429) return 'rate limited by Firecrawl (429)';
  return String(e.message || 'request failed') + (status ? ' (' + status + ')' : '');
};

let postings = [];
let rubrics = [];
const researchErrors = [];
for (let i = 0; i < results.length; i++) {
  const purpose = (queries[i] && queries[i].json && queries[i].json.purpose) || (i === 0 ? 'postings' : 'rubric');
  const err = errorOf(results[i]);
  if (err) {
    researchErrors.push(purpose + ' search: ' + err);
    continue;
  }
  if (purpose === 'postings') postings = postings.concat(webResults(results[i]));
  else rubrics = rubrics.concat(webResults(results[i]));
}

const blobs = postings.map(r => [r.markdown, r.description, r.title].filter(Boolean).join(' ').toLowerCase());

// With zero postings every count is 0/0, which the critique prompt presents to the
// model as mechanically-counted fact. Send nothing rather than meaningless zeroes.
const keywordFrequency = blobs.length === 0 ? [] : keywords.map(kw => ({
  keyword: kw,
  postingsMentioning: blobs.filter(b => b.includes(kw.toLowerCase())).length,
  ofPostings: blobs.length,
}));

let marketCorpus = '';
for (const r of postings) {
  const body = String(r.markdown || r.description || '').trim();
  if (!body) continue;
  const block = '\n\n===== REPLACE_WITH_YOUR_SLACK_CHANNEL_ID POSTING: ' + (r.title || r.url || 'untitled') + ' =====\n' + body;
  if (marketCorpus.length + block.length > MAX_CORPUS) break;
  marketCorpus += block;
}

let rubricNotes = '';
for (const r of rubrics) {
  const block = '\n- ' + String(r.title || '').trim() + ': ' + String(r.description || '').trim();
  if (rubricNotes.length + block.length > MAX_RUBRIC) break;
  rubricNotes += block;
}

return [{
  json: {
    researchOk: postings.length > 0 || rubrics.length > 0,
    postingsFound: postings.length,
    rubricsFound: rubrics.length,
    researchErrors,
    keywordFrequency,
    marketCorpus: marketCorpus.trim(),
    rubricNotes: rubricNotes.trim(),
  },
}];

