const c = ($input.first().json || {}).output || {};
const recs = Array.isArray(c.recommendations) ? c.recommendations : [];

const numbered = recs.map((r, i) => {
  const impact = String(r.impact || 'medium').toLowerCase();
  const title = String(r.title || 'Untitled recommendation').replace(/\s+/g, ' ').trim().slice(0, 90);
  const quote = String(r.source_quote || '').replace(/\s+/g, ' ').trim().slice(0, 200);
  const detail = String(r.detail || '').trim();
  return {
    n: i + 1,
    impact,
    title,
    sourceQuote: quote,
    // The quote rides inside detail because Apply Approved Revisions only ever sees
    // title + detail - it never receives the corpus, so this is its only evidence.
    detail: quote
      ? detail + '\nSOURCE QUOTE (verbatim from the candidate material): "' + quote + '"'
      : detail + '\nNO SOURCE QUOTE SUPPLIED - this recommendation is unverified. Do not add any claim it implies.',
    label: (i + 1) + '. [' + impact.toUpperCase() + '] ' + title,
  };
});

if (!numbered.length) {
  numbered.push({
    n: 1,
    impact: 'low',
    title: 'No changes recommended',
    sourceQuote: '',
    detail: 'The reviewer found nothing worth changing in this draft.',
    label: '1. [LOW] No changes recommended',
  });
}

// Same nested shape the Fields UI produces - the JSON mode is not a flatter format.
const formFields = [
  {
    fieldLabel: 'Which recommendations should I apply?',
    fieldType: 'checkbox',
    fieldOptions: { values: numbered.map(r => ({ option: r.label })) },
    requiredField: false,
  },
  {
    fieldLabel: 'Anything else you want changed?',
    fieldType: 'textarea',
    placeholder: 'Optional - e.g. keep the 2016 helpdesk role, or cut it to one page',
    requiredField: false,
  },
];

const jd = $('Analyze JD Against Profile').first().json.output || {};
const corpusMeta = $('Build Resume Corpus').first().json || {};
const norm = $('Normalize JD').first().json || {};

// Everything downstream of the approval gate reads this blob out of the Data Table
// instead of $('UpstreamNode'). n8n does not restore pre-pause run data when a
// sendAndWait execution resumes, so cross-gate node references silently break.
const payload = {
  draftHtml: $('Write Tailored Resume').first().json.text || '',
  recommendations: numbered,
  overallScore: c.overall_score === undefined ? null : c.overall_score,
  verdict: c.verdict || '',
  company: jd.company || 'Unknown Company',
  roleTitle: jd.role_title || 'Unknown Role',
  matchScore: jd.match_score === undefined ? null : jd.match_score,
  // Report the candidate's own evidence, not the posting's requirement text - the
  // Slack label says "evidenced strengths" and m.requirement is the JD's wording.
  matchedStrengths: (jd.matched_strengths || []).map(m => (m.evidence || m.requirement || '') + (m.evidence && m.requirement ? '\n_answers: ' + m.requirement + '_' : '')),
  gaps: jd.gaps || [],
  includedFiles: corpusMeta.includedFiles || [],
  skippedFiles: corpusMeta.skippedFiles || [],
  slackChannel: norm.slackChannel || '',
  threadTs: norm.threadTs || '',
};

return [{
  json: {
    overallScore: payload.overallScore,
    verdict: payload.verdict,
    marketEvidence: c.market_evidence || [],
    strengths: c.strengths || [],
    weaknesses: c.weaknesses || [],
    recommendations: numbered,
    recommendationCount: numbered.length,
    recommendationSummary: ((s) => s.length > 2800 ? s.slice(0, 2800) + '\n\n_(truncated - full list is in the thread)_' : s)(numbered.map(r => '*' + r.label + '*\n' + r.detail).join('\n\n')),
    formJson: JSON.stringify(formFields),
    payload: JSON.stringify(payload),
  },
}];

