// State comes from the Data Table, never from $('UpstreamNode') - n8n drops all
// pre-pause run data when a sendAndWait execution resumes.
const row = $input.first().json || {};

let state = {};
try {
  state = JSON.parse(row.payload || '{}');
} catch (e) {
  state = {};
}

if (!state.draftHtml) {
  throw new Error('Could not restore the review state for execution ' + $execution.id + '. The resume draft is unavailable, so nothing was published.');
}

const recs = state.recommendations || [];

// The gate node itself IS restored on resume - it is the entry point - so this
// reference is safe where pre-gate ones are not.
const raw = $('Review & Approve Recommendations').first().json || {};

// responseType 'approval' reports the choice as a boolean. Versions differ on
// whether it lands under .data or at the top level, so check both. Anything that
// is not an explicit true counts as skip, which publishes the draft untouched.
const flag = (raw.data && raw.data.approved !== undefined) ? raw.data.approved : raw.approved;
const approvedAll = flag === true || flag === 'true';

const approved = approvedAll ? recs : [];

return [{
  json: {
    ...state,
    approved,
    approvedCount: approved.length,
    freeText: '',
    hasChanges: approved.length > 0,
    approvalFlag: flag === undefined ? null : flag,
    rawFormResponse: raw,
  },
}];

