const src = $input.first().json || {};

// Verified against Drive's HTML->Docs importer (see notes): single font name only,
// styled <p> instead of headings, <hr> instead of border-bottom.
const F = 'Calibri';
const CSS = {
  name:     'text-align:center;font-family:' + F + ';font-size:20pt;font-weight:700;color:#111111;margin:0 0 1pt 0;',
  contact:  'text-align:center;font-family:' + F + ';font-size:9.5pt;color:#444444;margin:0 0 8pt 0;',
  section:  'font-family:' + F + ';font-size:11pt;font-weight:700;color:#111111;margin:11pt 0 3pt 0;',
  hr:       'margin:1pt 0 3pt 0;',
  role:     'font-family:' + F + ';font-size:10.5pt;font-weight:700;color:#111111;margin:6pt 0 0 0;',
  rolemeta: 'font-family:' + F + ';font-size:9pt;font-style:italic;color:#555555;margin:0 0 2pt 0;',
  body:     'font-family:' + F + ';font-size:10pt;color:#222222;margin:0 0 3pt 0;text-align:left;',
  ul:       'margin:0 0 3pt 0;padding-left:16pt;',
  ol:       'margin:0 0 3pt 0;padding-left:16pt;',
  li:       'font-family:' + F + ';font-size:10pt;color:#222222;margin:0;',
  a:        'color:#1155cc;text-decoration:none;',
};

// Uppercase text nodes without mangling entities - &amp; must not become &AMP;.
const upperTextNodes = (s) => s.replace(/(^|>)([^<]+)/g, (m, pre, txt) =>
  pre + txt.replace(/&[a-z]+;|&#\d+;|[\s\S]/gi, (t) => (t.length > 1 ? t : t.toUpperCase())));

// 1. Sanitize - we control the document wrapper, so drop anything the model emitted.
let body = String(src.resumeHtml || '')
  .replace(/^﻿/, '')
  .replace(/^\s*```[a-z]*\s*/i, '')
  .replace(/\s*```\s*$/, '')
  .replace(/<!DOCTYPE[^>]*>/gi, '')
  .replace(/<\/?(?:html|head|body)\b[^>]*>/gi, '')
  .replace(/<style\b[\s\S]*?<\/style>/gi, '')
  .replace(/<script\b[\s\S]*?<\/script>/gi, '')
  .replace(/<meta\b[^>]*>/gi, '')
  .replace(/<title\b[\s\S]*?<\/title>/gi, '')
  .trim();

// 2. Role headers can arrive as loose inline content between a heading and its <ul>.
//    Give any such orphan run a real block element before classifying.
body = body.replace(
  /(^|<\/(?:h1|h2|h3|h4|p|ul|ol|div)>)([\s\S]*?)(?=<(?:ul|ol|h1|h2|h3|h4|p|div)\b|$)/gi,
  (m, before, run) => { const t = run.trim(); return t ? before + '<p>' + t + '</p>' : before; }
);

// 3. Classify every paragraph, splitting role headers onto their own meta line.
const firstH2 = body.search(/<h2\b/i);
body = body.replace(/<p\b[^>]*>([\s\S]*?)<\/p>/gi, (m, inner, offset) => {
  const t = inner.trim();
  if (!t) return '';
  if (firstH2 !== -1 && offset < firstH2) return '<p style="' + CSS.contact + '">' + t + '</p>';
  if (/^<strong\b/i.test(t)) {
    const parts = t.split(/<br\s*\/?>/i);
    const head = (parts.shift() || '').trim();
    const meta = parts.join(' ').replace(/\s+/g, ' ').trim();
    return '<p style="' + CSS.role + '">' + head + '</p>' +
      (meta ? '<p style="' + CSS.rolemeta + '">' + meta + '</p>' : '');
  }
  return '<p style="' + CSS.body + '">' + t + '</p>';
});

// 4. Headings become styled paragraphs; the section rule becomes a native <hr>.
body = body.replace(/<h1\b[^>]*>([\s\S]*?)<\/h1>/gi,
  (m, inner) => '<p style="' + CSS.name + '">' + inner.trim() + '</p>');
body = body.replace(/<h([234])\b[^>]*>([\s\S]*?)<\/h\1>/gi,
  (m, lvl, inner) => '<p style="' + CSS.section + '">' + upperTextNodes(inner.trim()) +
    '</p>');

// 5. Linkify bare emails and URLs. The writer is told to emit anchors, but the Doc
//    import only makes text clickable if a real <a href> is there, so guarantee it here.
//    Existing anchors and anything inside a tag are left untouched.
const LINKABLE = /([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})|((?:https?:\/\/|www\.)[^\s<>"'&]+|(?:[A-Za-z0-9-]+\.)+(?:com|org|net|io|dev|ai|co|edu|gov|me|app)(?:\/[^\s<>"'&]*)?)/gi;
body = body
  .split(/(<a\b[^>]*>[\s\S]*?<\/a>|<[^>]+>)/i)
  .map((chunk, i) => (i % 2 ? chunk : chunk.replace(LINKABLE, (m, email) => {
    const trail = (m.match(/[.,;:)\]]+$/) || [''])[0];
    const core = trail ? m.slice(0, m.length - trail.length) : m;
    if (!core) return m;
    const href = email ? 'mailto:' + core
      : /^https?:\/\//i.test(core) ? core
      : 'https://' + core;
    return '<a href="' + href + '">' + core + '</a>' + trail;
  })))
  .join('');

// 6. Lists and links.
for (const tag of ['ul', 'ol', 'li', 'a']) {
  body = body.replace(new RegExp('<' + tag + '\\b([^>]*)>', 'gi'), (m, attrs) => {
    const kept = attrs.replace(/\s*style\s*=\s*"[^"]*"/gi, '');
    return '<' + tag + kept + ' style="' + CSS[tag] + '">';
  });
}

const doc = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body>' + body + '</body></html>';

return [{ json: { ...src, resumeHtml: doc } }];

const doc = $input.first().json || {};

// 0.5in top/bottom, 0.6in left/right.
const requests = [{
  updateDocumentStyle: {
    documentStyle: {
      marginTop: { magnitude: 36, unit: 'PT' },
      marginBottom: { magnitude: 36, unit: 'PT' },
      marginLeft: { magnitude: 43.2, unit: 'PT' },
      marginRight: { magnitude: 43.2, unit: 'PT' },
    },
    fields: 'marginTop,marginBottom,marginLeft,marginRight',
  },
}];

// Section headings are the 11pt bold all-caps paragraphs Style Resume HTML emits.
// Name is 20pt, role headers 10.5pt, body 10pt - so size+bold is unambiguous.
for (const el of ((doc.body || {}).content || [])) {
  const p = el.paragraph;
  if (!p) continue;
  const runs = (p.elements || []).filter(e => e.textRun);
  if (!runs.length) continue;
  const ts = runs[0].textRun.textStyle || {};
  const size = ts.fontSize ? ts.fontSize.magnitude : null;
  const text = runs.map(r => r.textRun.content).join('').replace(/\n/g, '').trim();
  if (!ts.bold || size !== 11 || !text || text !== text.toUpperCase()) continue;
  requests.push({
    updateParagraphStyle: {
      range: { startIndex: el.startIndex, endIndex: el.endIndex },
      paragraphStyle: {
        borderBottom: {
          color: { color: { rgbColor: { red: 0.6, green: 0.6, blue: 0.6 } } },
          width: { magnitude: 1, unit: 'PT' },
          padding: { magnitude: 2, unit: 'PT' },
          dashStyle: 'SOLID',
        },
      },
      fields: 'borderBottom',
    },
  });
}

return [{ json: { batchBody: JSON.stringify({ requests }), headingsRuled: requests.length - 1 } }];
